patch.content:
/ {
	/*
	 * Create a simple power domain for test purposes.
	 * This domain is always on.
	 */
	test_domain: test_domain {
		compatible = "zephyr,power-domain";
		#power-domain-cells = <0>;
		status = "okay";
	};

	/* Test devices */
	test_dev_a: test_dev_a {
		compatible = "test-device";
		power-domain = <&test_domain>;
		status = "okay";
	};

	test_dev_b: test_dev_b {
		compatible = "test-device";
		power-domain = <&test_domain>;
		status = "okay";
	};

	test_dev_c: test_dev_c {
		compatible = "test-device";
		status = "okay";
	};
};
